<template>
  <div class="leader" v-if="leader">
    <div class="address-info">
      <p v-show="nowAddress">当前地址</p>
      <p class="address">{{nowAddress}}</p>
      <router-link to="/leaderList" class="btn"><button class="main-color-font main-color-border">附近其他团长</button></router-link>
    </div>
    <div class="leader-info">
      <div class="avatar"><img :src="leader.avatar" alt=""></div>
      <div class="name">团长：{{leader.name}}</div>
      <div class="gray" v-if="leader.pick_address">社区：{{leader.pick_address.name}}</div>
      <div class="gray">微信号：{{leader.wx_number}}</div>

      <a href="tel:12345678910" class="phone">
        <div>
          <i class="icon iconfont">&#xe6dd;</i>电话：<span class="num">{{leader.phone}}</span>
        </div>
      </a>
      <div class="address" v-if="leader.pick_address"><i class="icon iconfont">&#xe60b;</i>地址：{{leader.pick_address.pick_addr}}</div>

      <div class="btn"><button class="main-color-bg" @click="selectLeader">选择此团长</button></div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'Leader',
  data () {
    return {
      leader_id: '',
      lng: '',
      lat: '',
      leader: '',
      nowAddress: '',
      wxLoad: false,
      configTimer: ''
    }
  },
  created () {
    this.leader_id = this.$util.storage.get('leader_id')
    if (this.leader_id) {
      this.getLeaderInfo()
    }
    let _this = this
    this.configTimer = setInterval(function () {
      if (_this.$global.config.config) {
        clearTimeout(_this.configTimer)
        if (_this.$util.checkWeixin() && _this.$util.checkAndroid()) {
          _this.$util.getWxconfig(_this.getLocation)
        } else {
          _this.getLocation()
        }
      }
    }, 50)
  },
  beforeRouteLeave (to, from, next) {
    if (to.name == 'index' && !this.$util.storage.get('leader_id')) {
      console.log('222222299999')
      this.$router.go(-1)
    }
    next()
  },
  methods: {
    getLocation () {
      // 获取定位信息
      // this.$messageBox.alert('定位')
      this.$util.getLocation(this.getLocationOk)
    },
    // 选择此团长
    selectLeader () {
      this.$util.storage.set('leader_id', this.leader.id)
      this.$router.back()
    },
    // 定位成功的回调
    getLocationOk (res) {
      // this.$messageBox.confirm(JSON.stringify(res))
      if (!res.errorMsg) {
        this.lng = res.lng
        this.lat = res.lat

        this.$util.getAdressDetail(this.lng, this.lat, this.getAddressBack)
        if (!this.leader_id) {
          this.getLeaderInfo()
        }
      } else if (!this.leader_id) {
        this.$messageBox.alert(res.errorMsg).then(action => {
          this.$router.push('/leaderList')
        })
      }
    },
    getAddressBack (obj) {
      if (obj.status === 0) {
        this.nowAddress = obj.result.formatted_address + obj.result.sematic_description
        this.$global.nowAddress = this.nowAddress
      }
    },
    async getLeaderInfo () {
      let param = {
        leader_id: this.leader_id
      }
      if (!param.leader_id) {
        param.lng = this.lng
        param.lat = this.lat
      }
      let res = await this.$api.getLeaderInfo(param)
      if (!res) {
        if (param.leader_id) {
          this.leader_id = ''
          this.$util.storage.remove('leader_id')
          this.getLeaderInfo()
        }
        return
      }
      this.leader = res
    }
  }
}
</script>

<style lang="stylus" scoped>
.leader
  background #fff
  .address-info
    padding 20px 0
    text-align center
    color #999
    .address
      color #000000
      font-size 16px
      font-weight bold
      margin 10px auto
      max-width 80%
      line-height 1.5
    .btn
      button
        background #fff
        border 1PX solid $color-main
        color $color-main
        padding 5px 12px
        border-radius 15px
        &:active
          opacity .5
  .leader-info
    padding 30px 0
    margin 15px
    box-shadow 0 5px 40px #e5e5e5
    border 1PX solid #efefef
    border-radius 5px
    text-align center
    line-height 1.5
    .avatar
      img
        width 40px
        height 40px
        border-radius 50%
        margin-bottom 10px
    .name
      font-size 18px
    .gray
      color #999999
    .phone, .address
      font-size 14px
      .icon
        color #7ab900
        padding-right 5px
      .num
        color blue
    .phone
      display inline-block
      margin-top 20px
      color #000
    .address
      margin-top 5px
    .btn
      button
        background #fff
        color #fff
        padding 10px 30px
        border-radius 20px
        background $color-main
        margin-top 15px
        font-size 14px
        &:active
          opacity .7
</style>
